import { Link, useParams, useLocation } from "@tanstack/react-router";
import { cn } from "@/lib/utils";
import { CheckCircle2, Lock, FileText, Video } from "lucide-react";
import { CourseProgressBar } from "./progress-bar";

// ##################
// authored (generated by antigravity, Jun 24 2026 21:18 WITA)
// ##################

export interface MaterialItem {
  id: string;
  title: string;
  type: string;
  duration: number | null;
  orderIndex: number;
}

export interface MaterialSidebarProps {
  materials: MaterialItem[];
  assessments?: {
    id: string;
    title: string;
    type: string;
  }[];
  progresses: { materialId: string | null; completed: boolean }[];
  enrollmentId: string;
  progressPercentage: number;
}

export function MaterialSidebar({
  materials,
  assessments,
  progresses,
  enrollmentId,
  progressPercentage,
}: MaterialSidebarProps) {
  const { materiId } = useParams({ strict: false }) as { materiId?: string };
  const location = useLocation();

  // Calculate which material is currently unlocked based on sequential completion
  // A material is unlocked if all its predecessors are completed.
  const completedMaterialIds = new Set(
    progresses
      .filter((p) => p.completed && p.materialId)
      .map((p) => p.materialId),
  );

  let firstUncompletedIndex = materials.findIndex(
    (m) => !completedMaterialIds.has(m.id),
  );

  if (firstUncompletedIndex === -1) {
    firstUncompletedIndex = materials.length; // All completed
  }

  return (
    <div className="flex hidden h-full w-80 shrink-0 flex-col border-r bg-card md:flex">
      <div className="border-b p-4">
        <h3 className="mb-4 font-semibold">Materi Pelatihan</h3>
        <CourseProgressBar
          percentage={progressPercentage}
          completedCount={completedMaterialIds.size}
          totalCount={materials.length}
        />
      </div>
      <div className="flex-1 overflow-y-auto">
        <div className="space-y-1 p-2">
          {assessments
            ?.filter((a) => a.type === "pre_test")
            .map((assessment) => {
              const isActive = location.pathname.includes(
                `/ujian/${assessment.id}`,
              );
              return (
                <Link
                  key={assessment.id}
                  to="/pelatihan/belajar/$enrollmentId/ujian/$assessmentId"
                  params={{ enrollmentId, assessmentId: assessment.id }}
                  className={cn(
                    "flex items-start gap-3 rounded-md p-3 transition-colors",
                    isActive
                      ? "bg-primary/10 font-medium text-primary"
                      : "text-foreground hover:bg-muted",
                  )}
                >
                  <div className="mt-0.5 shrink-0">
                    <FileText className="h-5 w-5 text-primary" />
                  </div>
                  <div className="flex min-w-0 flex-col gap-1">
                    <span className="line-clamp-2 text-sm leading-snug">
                      Pre-Test
                    </span>
                  </div>
                </Link>
              );
            })}
          {materials.map((materi, index) => {
            const isCompleted = completedMaterialIds.has(materi.id);
            const isUnlocked = index <= firstUncompletedIndex;
            const isActive = materiId === materi.id;

            return (
              <Link
                key={materi.id}
                to="/pelatihan/belajar/$enrollmentId/materi/$materiId"
                params={{ enrollmentId, materiId: materi.id }}
                disabled={!isUnlocked}
                className={cn(
                  "flex items-start gap-3 rounded-md p-3 transition-colors",
                  isActive
                    ? "bg-primary/10 font-medium text-primary"
                    : isUnlocked
                      ? "text-foreground hover:bg-muted"
                      : "pointer-events-none text-muted-foreground opacity-50",
                )}
              >
                <div className="mt-0.5 shrink-0">
                  {isCompleted ? (
                    <CheckCircle2 className="h-5 w-5 text-green-500" />
                  ) : !isUnlocked ? (
                    <Lock className="h-5 w-5 text-muted-foreground" />
                  ) : materi.type === "video" ? (
                    <Video className="h-5 w-5 text-primary" />
                  ) : (
                    <FileText className="h-5 w-5 text-primary" />
                  )}
                </div>
                <div className="flex min-w-0 flex-col gap-1">
                  <span className="line-clamp-2 text-sm leading-snug">
                    {index + 1}. {materi.title}
                  </span>
                  {materi.duration && (
                    <span className="text-xs text-muted-foreground">
                      {Math.floor(materi.duration / 60)} menit
                    </span>
                  )}
                </div>
              </Link>
            );
          })}
          {assessments
            ?.filter((a) => a.type === "post_test")
            .map((assessment) => {
              const isActive = location.pathname.includes(
                `/ujian/${assessment.id}`,
              );
              const isUnlocked = firstUncompletedIndex >= materials.length; // Post-test unlocked if all materials done
              return (
                <Link
                  key={assessment.id}
                  to="/pelatihan/belajar/$enrollmentId/ujian/$assessmentId"
                  params={{ enrollmentId, assessmentId: assessment.id }}
                  disabled={!isUnlocked}
                  className={cn(
                    "flex items-start gap-3 rounded-md p-3 transition-colors",
                    isActive
                      ? "bg-primary/10 font-medium text-primary"
                      : isUnlocked
                        ? "text-foreground hover:bg-muted"
                        : "pointer-events-none text-muted-foreground opacity-50",
                  )}
                >
                  <div className="mt-0.5 shrink-0">
                    {!isUnlocked ? (
                      <Lock className="h-5 w-5 text-muted-foreground" />
                    ) : (
                      <FileText className="h-5 w-5 text-primary" />
                    )}
                  </div>
                  <div className="flex min-w-0 flex-col gap-1">
                    <span className="line-clamp-2 text-sm leading-snug">
                      Post-Test
                    </span>
                  </div>
                </Link>
              );
            })}
        </div>
      </div>
    </div>
  );
}
